import { toast } from "react-toastify";

export default function toastMessage(error, message = "something went wrong") {
  if (error === false) {
    toast.success(message, {
      autoClose: 6000,
      pauseOnHover: true,
    });
  } else {
    toast.error(message, {
      autoClose: 10000, // 10 seconds duration for errors
      pauseOnHover: true,
    });
  }
}
